using HRIS.Api.Data; using HRIS.Api.Models; using Microsoft.EntityFrameworkCore;
namespace HRIS.Api.Repositories;
public class DeclarationRepository : IDeclarationRepository { private readonly AppDbContext _db; public DeclarationRepository(AppDbContext db)=>_db=db; public Task<List<DeclarationTemplate>> GetTemplatesAsync(bool includeInactive=false)=>_db.DeclarationTemplates.Where(x=>includeInactive||x.IsActive).OrderBy(x=>x.Title).ToListAsync(); public Task<DeclarationTemplate?> GetTemplateByIdAsync(int id)=>_db.DeclarationTemplates.FirstOrDefaultAsync(x=>x.Id==id); public Task<List<DeclarationSubmission>> GetSubmissionsAsync(int? employeeId=null)=>_db.DeclarationSubmissions.Include(x=>x.Template).Include(x=>x.Employee).Include(x=>x.Document).Where(x=>employeeId==null||x.EmployeeId==employeeId).OrderByDescending(x=>x.AgreedAt).ToListAsync(); public Task<DeclarationSubmission?> GetSubmissionByIdAsync(int id)=>_db.DeclarationSubmissions.Include(x=>x.Template).Include(x=>x.Employee).Include(x=>x.Document).FirstOrDefaultAsync(x=>x.Id==id); public async Task<DeclarationTemplate> AddTemplateAsync(DeclarationTemplate x){_db.DeclarationTemplates.Add(x);await _db.SaveChangesAsync();return x;} public async Task UpdateTemplateAsync(DeclarationTemplate x)=>await _db.SaveChangesAsync(); public async Task<DeclarationSubmission> AddSubmissionAsync(DeclarationSubmission x){_db.DeclarationSubmissions.Add(x);await _db.SaveChangesAsync();return x;} }
